<?php
namespace App\Finance;
use App\Harvest\HarvestBook;
use App\Field\FieldProblem;
class ContractPayments
{
 public function __construct(private \CodeIgniter\Database\BaseConnection $db){}
 private function lock(string $table,int $id):?array{return $this->db->query('SELECT * FROM '.$this->db->escapeIdentifiers($this->db->prefixTable($table)).' WHERE id=?'.($this->db->getPlatform()==='MySQLi'?' FOR UPDATE':''),[$id])->getRowArray();}
 private function tx(callable $fn):array{$this->db->transBegin();try{$r=$fn();if(!$this->db->transStatus()||!$this->db->transCommit())throw new \RuntimeException('Persistence');return $r;}catch(\Throwable $e){$this->db->transRollback();if($e instanceof FieldProblem)throw $e;log_message('error','Contract finance: {error}',['error'=>$e->getMessage()]);throw new FieldProblem(409,'Não foi possível confirmar. Reabra e tente novamente.');}}
 public static function uuid($id):string{if(!is_string($id)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/D',$id))throw new FieldProblem(422,'Identificador inválido.');return $id;}
 public static function money($value):int{$n=HarvestBook::decimal($value,false);if(\Brick\Math\BigDecimal::of($n)->toScale(2,\Brick\Math\RoundingMode::DOWN)->compareTo($n)!==0)throw new FieldProblem(422,'Use um valor positivo com duas casas decimais.');return ProductionBook::cents($n);}
 public function audit(string $resource,int $id,string $action,?array $before,array $after):void{$this->db->table('agri_admin_audit')->insert(['resource'=>$resource,'record_id'=>$id,'actor_id'=>auth()->id(),'action'=>$action,'before_json'=>$before?json_encode($before):null,'after_json'=>json_encode($after),'created_at'=>gmdate('Y-m-d H:i:s')]);}
 private function replay(string $table,string $uuid,string $hash):?array{$r=$this->db->table($table)->where('request_id',$uuid)->get()->getRowArray();if($r&&!hash_equals($r['request_hash'],$hash))throw new FieldProblem(409,'Identificador já usado com outros dados.');return $r;}
 public function pending(int $harvest,int $worker,string $from,string $to):array{
  HarvestBook::requireAdmin();HarvestBook::date($from);HarvestBook::date($to);if($from>$to)throw new FieldProblem(422,'Período inválido.');
  $rows=$this->db->table('agri_harvest_allocations a')->select('a.*,l.work_date,l.service_name,l.payment_unit_name AS unit_name,h.name AS contract_name,h.id AS harvest_id,w.name AS worker_name,p.name AS pool_name')->join('agri_work_logs l','l.id=a.work_log_id')->join('agri_harvests h','h.id=l.harvest_id')->join('agri_workers w','w.id=a.worker_id')->join('agri_contract_settlement_items i','i.work_log_id=a.work_log_id AND i.worker_id=a.worker_id','left')->join('agri_work_log_attendees t','t.work_log_id=a.work_log_id AND t.worker_id=a.worker_id')->join('agri_work_pools p','p.work_log_id=a.work_log_id AND p.pool_key=t.pool_key','left')->where('i.settlement_id',null)->where('l.status','closed')->where('l.harvest_id',$harvest)->where('a.worker_id',$worker)->where('l.work_date >=',$from)->where('l.work_date <=',$to)->orderBy('l.work_date')->orderBy('a.work_log_id')->get()->getResultArray();
  return ['items'=>$rows,'preview_hash'=>hash('sha256',json_encode([$harvest,$worker,$from,$to,$rows]))];
 }
 public function create(array $in):array{HarvestBook::requireAdmin();$uuid=self::uuid($in['request_id']??null);$hash=hash('sha256',json_encode([$in,auth()->id()]));return $this->tx(function()use($in,$uuid,$hash){$h=(int)($in['harvest_id']??0);$w=(int)($in['worker_id']??0);if(!$this->lock('agri_harvests',$h)||!$this->lock('agri_workers',$w))throw new FieldProblem(422,'Selecione contrato e trabalhador.');if($old=$this->replay('agri_contract_settlements',$uuid,$hash))return ['item'=>$this->detail((int)$old['id'])];$from=HarvestBook::date($in['date_from']??null);$to=HarvestBook::date($in['date_to']??null);$preview=$this->pending($h,$w,$from,$to);if(!is_string($in['preview_hash']??null)||!hash_equals($preview['preview_hash'],$in['preview_hash']))throw new FieldProblem(409,'A produção mudou. Consulte novamente.');$items=$preview['items'];if(!$items)throw new FieldProblem(422,'Sem produção validada por fechar.');
  $pending=$this->db->table('agri_work_logs l')->join('agri_work_log_attendees a','a.work_log_id=l.id')->where('l.harvest_id',$h)->where('a.worker_id',$w)->where('a.present',1)->whereIn('l.status',['draft','submitted'])->where('l.work_date >=',$from)->where('l.work_date <=',$to)->countAllResults();if($pending)throw new FieldProblem(409,'Existem trabalhos por validar para este trabalhador no período.');
  $total=0;foreach($items as$i)$total+=(int)$i['amount_cents'];if($total>9000000000000000)throw new FieldProblem(422,'Total fora do limite permitido.');$this->db->table('agri_contract_settlements')->insert(['harvest_id'=>$h,'worker_id'=>$w,'date_from'=>$from,'date_to'=>$to,'total_cents'=>$total,'paid_cents'=>0,'version'=>1,'created_by'=>auth()->id(),'created_at'=>gmdate('Y-m-d H:i:s'),'request_id'=>$uuid,'request_hash'=>$hash]);$id=(int)$this->db->insertID();foreach($items as$i)$this->db->table('agri_contract_settlement_items')->insert(['settlement_id'=>$id,'work_log_id'=>$i['work_log_id'],'worker_id'=>$w]);
  $credit=0;$logIds=array_map(fn($r)=>(int)$r['work_log_id'],$items);$moves=$this->db->table('agri_harvest_movements')->where('harvest_id',$h)->where('worker_id',$w)->where('kind','payment')->where('settlement_id',null)->orderBy('id')->get()->getResultArray();foreach($moves as$m){if($m['work_log_id']!==null&&!in_array((int)$m['work_log_id'],$logIds,true))continue;$used=(int)($this->db->table('agri_contract_payment_credits')->selectSum('amount_cents','total')->where('movement_id',$m['id'])->get()->getRowArray()['total']??0);$use=min($total-$credit,(int)$m['amount_cents']-$used);if($use>0){$this->db->table('agri_contract_payment_credits')->insert(['settlement_id'=>$id,'movement_id'=>$m['id'],'amount_cents'=>$use]);$credit+=$use;}}
  $this->db->table('agri_contract_settlements')->where('id',$id)->update(['paid_cents'=>$credit]);$r=$this->detail($id);$this->audit('settlements',$id,'create',null,$r);return ['item'=>$r];});}
 public function detail(int $id):array{HarvestBook::requireAdmin();$r=$this->db->table('agri_contract_settlements s')->select('s.*,w.name AS worker_name,h.name AS contract_name')->join('agri_workers w','w.id=s.worker_id')->join('agri_harvests h','h.id=s.harvest_id')->where('s.id',$id)->get()->getRowArray();if(!$r)throw new FieldProblem(404,'Fecho inexistente.');unset($r['request_hash']);$r['items']=$this->db->table('agri_contract_settlement_items i')->select('a.*,l.work_date,l.payment_unit_name AS unit_name,t.pool_key,p.name AS pool_name')->join('agri_harvest_allocations a','a.work_log_id=i.work_log_id AND a.worker_id=i.worker_id')->join('agri_work_logs l','l.id=i.work_log_id')->join('agri_work_log_attendees t','t.work_log_id=i.work_log_id AND t.worker_id=i.worker_id')->join('agri_work_pools p','p.work_log_id=i.work_log_id AND p.pool_key=t.pool_key','left')->where('i.settlement_id',$id)->get()->getResultArray();$r['payments']=$this->db->table('agri_harvest_movements')->select('id,paid_on,amount_cents,reference,method,notes')->where('settlement_id',$id)->get()->getResultArray();$r['credits']=$this->db->table('agri_contract_payment_credits c')->select('c.amount_cents,m.paid_on,m.reference,m.id AS movement_id')->join('agri_harvest_movements m','m.id=c.movement_id')->where('c.settlement_id',$id)->get()->getResultArray();return $r;}
 public function pay(int $id,array $in):array{HarvestBook::requireAdmin();return $this->tx(function()use($id,$in){$original=$this->detail($id);$this->lock('agri_harvests',(int)$original['harvest_id']);$s=$this->lock('agri_contract_settlements',$id);$uuid=self::uuid($in['request_id']??null);$old=$this->db->table('agri_harvest_movements')->where('request_id',$uuid)->get()->getRowArray();if(!$old&&(int)$s['version']!==($in['version']??null))throw new FieldProblem(409,'Fecho alterado. Reabra os dados.');$payload=$in;unset($payload['version']);$payload['kind']='payment';$payload['worker_id']=(int)$s['worker_id'];$payload['settlement_id']=$id;(new HarvestBook($this->db))->movement((int)$s['harvest_id'],$payload);return ['item'=>$this->detail($id)];});}
 public function expense(int $h,array $in):array{HarvestBook::requireAdmin();$uuid=self::uuid($in['request_id']??null);$hash=hash('sha256',json_encode([$h,$in,auth()->id()]));return $this->tx(function()use($h,$in,$uuid,$hash){if(!$this->lock('agri_harvests',$h))throw new FieldProblem(404,'Contrato inexistente.');if($old=$this->replay('agri_contract_expenses',$uuid,$hash))return ['item'=>$old];$description=$in['description']??'';if(!is_string($description)||trim($description)===''||mb_strlen($description)>160)throw new FieldProblem(422,'Descreva a despesa.');$date=HarvestBook::date($in['recognized_on']??null);$due=empty($in['due_on'])?null:HarvestBook::date($in['due_on']);$amount=self::money($in['amount']??null);$r=['harvest_id'=>$h,'description'=>trim($description),'amount_cents'=>$amount,'recognized_on'=>$date,'due_on'=>$due,'request_id'=>$uuid,'request_hash'=>$hash,'created_by'=>auth()->id(),'created_at'=>gmdate('Y-m-d H:i:s')];$this->db->table('agri_contract_expenses')->insert($r);$id=(int)$this->db->insertID();$this->audit('expenses',$id,'create',null,$r);return ['item'=>['id'=>$id]+$r];});}
}
